<?php
$symbol = match ($store['currency']) { 'USD' => 'US$', 'EUR' => '€', default => 'RD$' };
$products = $catalog['products'];
$allProducts = $allCatalog['products'] ?? $products;
$navigationCatalog = $allCatalog ?? $catalog;
$whatsapp = preg_replace('/\D+/', '', (string) ($store['whatsapp'] ?? ''));
$availableProducts = count(array_filter($allProducts, static fn (array $product): bool => (bool) ($product['available'] ?? false)));
$categoryCounts = [];
foreach ($allProducts as $product) {
    $name = trim((string) ($product['category'] ?? ''));
    if ($name !== '') {
        $categoryCounts[mb_strtolower($name)] = ($categoryCounts[mb_strtolower($name)] ?? 0) + 1;
    }
}
$brands = array_values(array_filter($navigationCatalog['brands'] ?? []));
$featuredProducts = array_slice(array_values(array_filter(
    $allProducts,
    static fn (array $product): bool => (bool) ($product['available'] ?? false)
)), 0, 8);
$newProducts = array_slice($allProducts, 0, 8);
$isFiltered = $search !== '' || $category !== '';
$businessType = (string) ($store['resolved_business_type'] ?? 'general');
$isRestaurant = $businessType === 'restaurant';
$isElectronics = $businessType === 'electronics';
$heroTitle = trim((string) ($store['hero_title'] ?? ''));
$heroText = trim((string) ($store['hero_text'] ?? ''));
if ($isRestaurant && ($heroTitle === '' || $heroTitle === 'Todo lo que buscas en un solo lugar')) {
    $heroTitle = 'Tus sabores favoritos, listos para ordenar';
}
if ($isRestaurant && ($heroText === '' || $heroText === 'Explora nuestros productos y consulta tus facturas cuando lo necesites.')) {
    $heroText = 'Explora el menú, agrega tus platos al carrito y elige retiro o entrega.';
}
if ($isElectronics && ($heroTitle === '' || $heroTitle === 'Todo lo que buscas en un solo lugar')) {
    $heroTitle = 'Tecnología, equipos y accesorios en un solo lugar';
}
$renderProductCard = static function (array $product, string $slug, string $symbol): void {
    $discount = $product['compare_price'] && $product['price'] !== null
        ? max(1, (int) round((1 - ((float) $product['price'] / (float) $product['compare_price'])) * 100))
        : 0;
    ?>
    <article class="product" data-product-card="<?= e($product['uid']) ?>">
        <div class="product-media">
            <a class="product-image-link" href="/store/<?= e($slug) ?>/products/<?= e($product['uid']) ?>"><?php if($product['image']): ?><img loading="lazy" src="<?= e($product['image']) ?>" alt="<?= e($product['name']) ?>"><?php else: ?><span class="placeholder">□</span><?php endif; ?></a>
            <span class="badge <?= $product['available']?'':'out' ?>"><?= $product['available']?'Disponible':'Agotado' ?></span>
            <?php if($discount): ?><span class="sale-badge">-<?= $discount ?>%</span><?php endif; ?>
            <span class="product-media-tools">
                <button type="button" data-favorite="<?= e($product['uid']) ?>" aria-label="Guardar en favoritos">♡</button>
                <button type="button" data-quick="<?= e($product['uid']) ?>" aria-label="Vista rápida">⌕</button>
            </span>
        </div>
        <div class="product-body">
            <div class="product-meta"><?php if($product['category']): ?><span class="category"><?= e($product['category']) ?></span><?php endif; ?><span class="stock-note <?= $product['available']?'':'out' ?>"><?= $product['available'] ? 'En existencia' : 'Agotado' ?></span></div>
            <h3><a href="/store/<?= e($slug) ?>/products/<?= e($product['uid']) ?>"><?= e($product['name']) ?></a></h3>
            <p class="description"><?= e($product['description']) ?></p>
            <div class="product-bottom"><span class="price-wrap"><span class="price"><?= $product['price']!==null ? e($symbol.' '.number_format($product['price'],2)) : 'Consultar' ?></span><?php if($product['compare_price']): ?><span class="old-price"><?= e($symbol.' '.number_format((float)$product['compare_price'],2)) ?></span><?php endif; ?></span><div class="product-actions"><a class="view-product" href="/store/<?= e($slug) ?>/products/<?= e($product['uid']) ?>">Ver detalle</a><button class="add" type="button" data-add-uid="<?= e($product['uid']) ?>" <?= $product['available']?'':'disabled' ?> aria-label="Agregar <?= e($product['name']) ?>">+</button></div></div>
        </div>
    </article>
    <?php
};
$heroImages = is_array($store['hero_images'] ?? null) ? $store['hero_images'] : [];
$heroMode = (string) ($store['hero_background_mode'] ?? 'gradient');
if (in_array($heroMode, ['image', 'carousel'], true) && !$heroImages) $heroMode = 'color';
?>
