<div class="drawer-backdrop" data-backdrop></div>
<aside class="cart-drawer" data-drawer aria-hidden="true"><div class="drawer-head"><div><small data-drawer-kicker>Tu compra</small><h2 data-drawer-title style="margin:2px 0 0">Carrito</h2></div><button class="drawer-close" type="button" data-close aria-label="Cerrar">×</button></div><div class="drawer-items" data-drawer-items></div><div class="drawer-foot" data-drawer-foot><div class="drawer-total"><span>Subtotal</span><span data-drawer-total><?= e($symbol) ?> 0.00</span></div><a class="drawer-checkout" href="/store/<?= e($store['slug']) ?>/cart">Revisar carrito y pagar</a></div></aside>
<section class="quick-modal" data-quick-modal aria-hidden="true"><div class="quick-image" data-quick-image></div><div class="quick-copy"><button class="drawer-close" type="button" data-close aria-label="Cerrar">×</button><span class="category" data-quick-category></span><h2 data-quick-name></h2><div class="price-wrap"><strong class="price" data-quick-price></strong><span class="old-price" data-quick-old></span></div><p data-quick-description></p><div class="hero-actions"><button class="primary" type="button" data-quick-add>Agregar al carrito</button><a class="view-product" data-quick-link>Ver todos los detalles</a></div></div></section>
<div class="toast" data-toast role="status"></div>
<script>
(()=>{
const products=<?= json_encode($allProducts, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>,byUid=Object.fromEntries(products.map(product=>[String(product.uid),product])),cartKey=<?= json_encode('tmp-store-cart-'.$store['uid']) ?>,wishKey=<?= json_encode('tmp-store-wishlist-'.$store['uid']) ?>,symbol=<?= json_encode($symbol) ?>,slug=<?= json_encode($store['slug']) ?>;
let cart={},wishlist=[];try{cart=JSON.parse(localStorage.getItem(cartKey)||'{}')||{}}catch(e){}try{wishlist=JSON.parse(localStorage.getItem(wishKey)||'[]')||[]}catch(e){}
const money=value=>symbol+' '+Number(value||0).toLocaleString('es-DO',{minimumFractionDigits:2,maximumFractionDigits:2}),esc=value=>{const node=document.createElement('div');node.textContent=String(value??'');return node.innerHTML},attr=value=>esc(value).replace(/"/g,'&quot;'),backdrop=document.querySelector('[data-backdrop]'),drawer=document.querySelector('[data-drawer]'),modal=document.querySelector('[data-quick-modal]'),toast=document.querySelector('[data-toast]');let drawerMode='cart',quickProduct=null,toastTimer;
function notify(message){toast.textContent=message;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),1800)}
function cartCount(){return Object.values(cart).reduce((total,item)=>total+Number(item.quantity||0),0)}
function sync(){localStorage.setItem(cartKey,JSON.stringify(cart));localStorage.setItem(wishKey,JSON.stringify(wishlist));document.querySelectorAll('[data-cart-count]').forEach(node=>node.textContent=cartCount());document.querySelectorAll('[data-wishlist-count]').forEach(node=>node.textContent=wishlist.length);document.querySelectorAll('[data-favorite]').forEach(button=>{const active=wishlist.includes(String(button.dataset.favorite));button.classList.toggle('active',active);button.textContent=active?'♥':'♡'});renderDrawer()}
function add(uid,quantity=1){const product=byUid[String(uid)];if(!product||!product.available)return;const current=cart[product.uid]||{product,quantity:0};current.product=product;current.quantity=Math.min(99,Number(current.quantity||0)+quantity);cart[product.uid]=current;sync();notify('Producto agregado al carrito')}
function toggleWish(uid){uid=String(uid);wishlist=wishlist.includes(uid)?wishlist.filter(item=>item!==uid):[...wishlist,uid];sync();notify(wishlist.includes(uid)?'Guardado en favoritos':'Eliminado de favoritos')}
function renderDrawer(){if(!drawer)return;const box=drawer.querySelector('[data-drawer-items]'),foot=drawer.querySelector('[data-drawer-foot]'),title=drawer.querySelector('[data-drawer-title]'),kicker=drawer.querySelector('[data-drawer-kicker]');let entries;if(drawerMode==='wishlist'){entries=wishlist.map(uid=>byUid[uid]).filter(Boolean).map(product=>({product,quantity:1}));title.textContent='Favoritos';kicker.textContent='Tu selección';foot.hidden=true}else{entries=Object.values(cart).filter(item=>item?.product&&Number(item.quantity)>0);title.textContent='Carrito';kicker.textContent=cartCount()+' producto'+(cartCount()===1?'':'s');foot.hidden=false}if(!entries.length){box.innerHTML='<div class="empty"><h3>'+(drawerMode==='wishlist'?'Aún no tienes favoritos':'Tu carrito está vacío')+'</h3><p>Explora el catálogo y guarda los productos que te interesen.</p></div>'}else{box.innerHTML=entries.map(item=>{const product=item.product;return '<article class="drawer-item">'+(product.image?'<img src="'+attr(product.image)+'" alt="">':'<span class="drawer-placeholder">□</span>')+'<div><b>'+esc(product.name)+'</b><small>'+(drawerMode==='cart'?item.quantity+' × ':'')+(product.price===null?'Consultar':money(product.price))+'</small></div><button class="drawer-remove" type="button" data-drawer-remove="'+attr(product.uid)+'">×</button></article>'}).join('')}box.querySelectorAll('[data-drawer-remove]').forEach(button=>button.onclick=()=>{if(drawerMode==='wishlist')wishlist=wishlist.filter(uid=>uid!==button.dataset.drawerRemove);else delete cart[button.dataset.drawerRemove];sync()});const subtotal=Object.values(cart).reduce((sum,item)=>sum+(Number(item.product?.price)||0)*Number(item.quantity||0),0);drawer.querySelector('[data-drawer-total]').textContent=money(subtotal)}
function openLayer(type){backdrop.classList.add('open');if(type==='quick'){modal.classList.add('open');modal.setAttribute('aria-hidden','false')}else{drawerMode=type;renderDrawer();drawer.classList.add('open');drawer.setAttribute('aria-hidden','false')}document.body.style.overflow='hidden'}
function closeLayers(){backdrop.classList.remove('open');drawer.classList.remove('open');modal.classList.remove('open');drawer.setAttribute('aria-hidden','true');modal.setAttribute('aria-hidden','true');document.body.style.overflow=''}
document.querySelector('[data-mega-trigger]')?.addEventListener('click',event=>{event.stopPropagation();document.querySelector('[data-mega]').classList.toggle('open')});document.addEventListener('click',event=>{if(!event.target.closest('[data-mega]'))document.querySelector('[data-mega]')?.classList.remove('open')});
document.querySelectorAll('[data-add-uid]').forEach(button=>button.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();add(button.dataset.addUid);const original=button.textContent;button.textContent='✓';setTimeout(()=>button.textContent=original,850)}));
document.querySelectorAll('[data-favorite]').forEach(button=>button.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();toggleWish(button.dataset.favorite)}));
document.querySelectorAll('[data-quick]').forEach(button=>button.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();quickProduct=byUid[String(button.dataset.quick)];if(!quickProduct)return;modal.querySelector('[data-quick-image]').innerHTML=quickProduct.image?'<img src="'+attr(quickProduct.image)+'" alt="">':'<span class="placeholder">□</span>';modal.querySelector('[data-quick-category]').textContent=quickProduct.category||quickProduct.brand||'Producto';modal.querySelector('[data-quick-name]').textContent=quickProduct.name;modal.querySelector('[data-quick-price]').textContent=quickProduct.price===null?'Consultar':money(quickProduct.price);modal.querySelector('[data-quick-old]').textContent=quickProduct.compare_price?money(quickProduct.compare_price):'';modal.querySelector('[data-quick-description]').textContent=quickProduct.description||'Consulta todos los detalles y la disponibilidad actualizada.';modal.querySelector('[data-quick-link]').href='/store/'+encodeURIComponent(slug)+'/products/'+encodeURIComponent(quickProduct.uid);modal.querySelector('[data-quick-add]').disabled=!quickProduct.available;openLayer('quick')}));
document.querySelector('[data-quick-add]')?.addEventListener('click',()=>quickProduct&&add(quickProduct.uid));document.querySelectorAll('[data-cart-open]').forEach(button=>button.onclick=()=>openLayer('cart'));document.querySelectorAll('[data-wishlist-open]').forEach(button=>button.onclick=()=>openLayer('wishlist'));document.querySelectorAll('[data-close]').forEach(button=>button.onclick=closeLayers);backdrop.onclick=closeLayers;document.addEventListener('keydown',event=>{if(event.key==='Escape')closeLayers()});
<?php if($store['show_stock']): ?>document.querySelectorAll('[data-product-card]').forEach(card=>{const product=byUid[String(card.dataset.productCard)],badge=card.querySelector('.badge');if(product?.available&&product.stock!==null)badge.textContent=Number(product.stock).toLocaleString('es-DO',{maximumFractionDigits:0})+' disponibles'});<?php endif; ?>
sync();
})();
</script>
<?php if($heroMode==='carousel'&&count($heroImages)>1): ?><script>(()=>{const hero=document.querySelector('[data-hero-carousel]'),slides=[...hero.querySelectorAll('[data-hero-slide]')],dots=[...hero.querySelectorAll('[data-hero-dot]')],delay=<?= (int)($store['hero_carousel_interval']??6000) ?>;let index=0,timer;function show(next){index=(next+slides.length)%slides.length;slides.forEach((slide,i)=>slide.classList.toggle('active',i===index));dots.forEach((dot,i)=>dot.classList.toggle('active',i===index))}function start(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;clearInterval(timer);timer=setInterval(()=>show(index+1),delay)}dots.forEach((dot,i)=>dot.onclick=()=>{show(i);start()});hero.addEventListener('mouseenter',()=>clearInterval(timer));hero.addEventListener('mouseleave',start);document.addEventListener('visibilitychange',()=>document.hidden?clearInterval(timer):start());start()})();</script><?php endif; ?>
</body>
</html>
